COUNTRY_LENGTHS = {
    "AD": 24,
    "AT": 20,
    "BE": 16,
    "CH": 21,
    "DE": 22,
    "ES": 24,
    "FR": 27,
    "GB": 22,
    "IE": 22,
    "IT": 27,
    "LU": 20,
    "NL": 18,
    "NO": 15,
    "PL": 28,
    "PT": 25,
    "SE": 24,
}


def normalize_iban(iban: str) -> str:
    if not isinstance(iban, str):
        raise ValueError("iban must be a string")
    return iban.replace(" ", "").upper()


def validate_iban(iban: str) -> bool:
    if not isinstance(iban, str):
        return False
    normalized = normalize_iban(iban)
    if len(normalized) < 4:
        return False
    country = normalized[:2]
    # Characters 1-2 must be letters A-Z
    if not ("A" <= country[0] <= "Z" and "A" <= country[1] <= "Z"):
        return False
    if country not in COUNTRY_LENGTHS:
        return False
    if len(normalized) != COUNTRY_LENGTHS[country]:
        return False
    # Characters 3-4 must be digits
    if not ("0" <= normalized[2] <= "9" and "0" <= normalized[3] <= "9"):
        return False
    # Remaining BBAN characters must be alphanumeric A-Z / 0-9
    for ch in normalized[4:]:
        if not (("A" <= ch <= "Z") or ("0" <= ch <= "9")):
            return False
    # Mod-97 check
    rearranged = normalized[4:] + normalized[:4]
    digit_parts = []
    for ch in rearranged:
        if "0" <= ch <= "9":
            digit_parts.append(ch)
        elif "A" <= ch <= "Z":
            digit_parts.append(str(ord(ch) - ord("A") + 10))
        else:
            return False
    value = int("".join(digit_parts))
    return value % 97 == 1
